// Bricks: collision + bounce + score + drawing, all in one place.
for (const brick of state.bricks) {
  if (!brick.alive) continue;

  if (collides(state.ball, brick)) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    const overlapX = Math.min(state.ball.x + state.ball.r, brick.x + brick.w) - Math.max(state.ball.x - state.ball.r, brick.x);
    const overlapY = Math.min(state.ball.y + state.ball.r, brick.y + brick.h) - Math.max(state.ball.y - state.ball.r, brick.y);

    if (overlapX < overlapY) {
      state.ball.vx = -state.ball.vx;
      state.ball.x = state.ball.x < brick.x + brick.w / 2 ? brick.x - state.ball.r : brick.x + brick.w + state.ball.r;
    } else {
      state.ball.vy = -state.ball.vy;
      state.ball.y = state.ball.y < brick.y + brick.h / 2 ? brick.y - state.ball.r : brick.y + brick.h + state.ball.r;
    }
  }

  ctx.fillStyle = brickColor(brick.row);
  ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
}

